#include<bits/stdc++.h>
#include<atcoder/convolution>

using namespace std;
using namespace atcoder;

int main(){
  int n;
  cin >> n;
  vector<int> p(1000005,0);
  for(int i=0;i<n;i++){
    int a;
    cin >> a;
    p[a]=1;
  }
  long long res=0;
  auto c=convolution(p,p);
  for(int i=0;i<1000005;i++){
    if(p[i]==1){
      res+=(c[2*i]-1)/2;
    }
  }
  cout << res << "\n";
}
